// GENERATED by scripts/sync-live-api.sh from dashboard/known_users.php. Do not edit.
function beta_ku_fail(string $msg): void {
    while (ob_get_level() > 0) { ob_end_clean(); }
    http_response_code(400);
    header('Content-Type: application/json');
    echo json_encode(['success' => false, 'error' => $msg]);
    exit();
}
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    // Every beta request is fetch, so the live AJAX branch always answers.
    $_SERVER['HTTP_X_REQUESTED_WITH'] = 'XMLHttpRequest';
    if (isset($_POST['status']) && !in_array($_POST['status'], ['True', 'False'], true)) beta_ku_fail('Status must be True or False.');
    if (isset($_POST['username']) && !preg_match('/^[A-Za-z0-9_]{1,25}$/', (string) $_POST['username'])) beta_ku_fail('Unknown user.');
    foreach (['userId', 'deleteUserId'] as $k) { if (isset($_POST[$k]) && !ctype_digit((string) $_POST[$k])) beta_ku_fail('Unknown user.'); }
    if (isset($_POST['newWelcomeMessage']) && mb_strlen(trim((string) $_POST['newWelcomeMessage'])) > 255) beta_ku_fail('Welcome message is longer than 255 characters.');
}


// Page Title
$pageTitle = t('known_users_title');

// Include files for database and user data
require_once "/var/www/config/db_connect.php";
include '/var/www/dashboard/includes/userdata.php';
include "/var/www/dashboard/includes/mod_access.php";
include '/var/www/dashboard/includes/user_db_connect.php'; // FAST SHELL: connection only, no bulk table load
session_write_close();

// List endpoint first so the browser can paint skeletons, then fetch rows.
if (isset($_GET['ajax_action']) && $_GET['ajax_action'] === 'list') {
    header('Content-Type: application/json');
    try {
        $tzStmt = $db->prepare("SELECT timezone FROM profile");
        $tzStmt->execute();
        $tzRow = $tzStmt->get_result()->fetch_assoc();
        $tzStmt->close();
        date_default_timezone_set($tzRow['timezone'] ?? 'UTC');

        $stmt = $db->prepare("SELECT id, username, first_seen, last_seen, welcome_message, status FROM seen_users ORDER BY id");
        $stmt->execute();
        $rows = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
        $stmt->close();
        foreach ($rows as &$row) {
            foreach (['first_seen', 'last_seen'] as $seenCol) {
                $seenVal = $row[$seenCol] ?? '';
                if (!empty($seenVal) && $seenVal !== '0000-00-00 00:00:00') {
                    $row[$seenCol] = date('Y-m-d H:i:s', strtotime($seenVal));
                } else {
                    $row[$seenCol] = '';
                }
            }
        }
        unset($row);
        echo json_encode(['success' => true, 'users' => $rows, 'total' => count($rows)]);
    } catch (mysqli_sql_exception $e) {
        http_response_code(500);
        echo json_encode(['success' => false, 'error' => $e->getMessage()]);
    }
    exit();
}

// Fetch the total number of users in the seen_users table
$totalUsersSTMT = $db->prepare("SELECT COUNT(*) as total_users FROM seen_users");
$totalUsersSTMT->execute();
$totalUsersResult = $totalUsersSTMT->get_result()->fetch_assoc();
$totalUsers = (int)($totalUsersResult['total_users'] ?? 0);
$totalUsersSTMT->close();

// Cache for banned users
$cacheExpiration = 86400; // 24 hours
$loggedInUsername = $_SESSION['username'];
$cacheBaseDir = "/var/www/cache/known_users";
$cacheFile = "$cacheBaseDir/$loggedInUsername.json";
$cacheWarningMessage = null; // Initialize warning message

if (!is_dir($cacheBaseDir)) {
  if (!mkdir($cacheBaseDir, 0755, true) && !is_dir($cacheBaseDir)) {
    $cacheWarningMessage = t('known_users_cache_dir_error', ['dir' => $cacheBaseDir]);
    error_log($cacheWarningMessage . " User: " . $loggedInUsername);
  }
}
$bannedUsersCache = [];
if (file_exists($cacheFile) && time() - filemtime($cacheFile) < $cacheExpiration) {
    $cacheContent = file_get_contents($cacheFile);
    if ($cacheContent) {
        $bannedUsersCache = json_decode($cacheContent, true);
    }
} else {
    // Clear the cache if it is expired
    $bannedUsersCache = [];
}

// Handle POST requests for updates. The page posts in the background and gets JSON back; other posts redirect.
if ($_SERVER["REQUEST_METHOD"] == "POST") {
  $handled = false;
  $ok = false;
  if (isset($_POST['username']) && isset($_POST['status'])) {
    $handled = true;
    $dbusername = (string) $_POST['username'];
    $status = $_POST['status'] === 'True' ? 'True' : 'False';
    $updateQuery = $db->prepare("UPDATE seen_users SET status = ? WHERE username = ?");
    $updateQuery->bind_param('ss', $status, $dbusername);
    $ok = $updateQuery->execute();
    $updateQuery->close();
  } elseif (isset($_POST['userId']) && isset($_POST['newWelcomeMessage'])) {
    $handled = true;
    $userId = (int) $_POST['userId'];
    $newWelcomeMessage = mb_substr(trim((string) $_POST['newWelcomeMessage']), 0, 255);
    if (preg_match('/[\x{10000}-\x{10FFFF}]/u', $newWelcomeMessage)) {
      $ok = false;
      $errorDetail = "Emoji aren't supported in welcome messages.";
    } else try {
      $messageQuery = $db->prepare("UPDATE seen_users SET welcome_message = ? WHERE id = ?");
      $messageQuery->bind_param('si', $newWelcomeMessage, $userId);
      $ok = $messageQuery->execute();
      $messageQuery->close();
    } catch (mysqli_sql_exception $e) {
      $ok = false;
      $errorDetail = $e->getMessage();
      error_log("known_users welcome save failed for user $userId: " . $errorDetail);
    }
  } elseif (isset($_POST['deleteUserId'])) {
    $handled = true;
    $deleteUserId = (int) $_POST['deleteUserId'];
    $deleteQuery = $db->prepare("DELETE FROM seen_users WHERE id = ?");
    $deleteQuery->bind_param('i', $deleteUserId);
    $ok = $deleteQuery->execute();
    $deleteQuery->close();
  }
  if ($handled) {
    if (($_SERVER['HTTP_X_REQUESTED_WITH'] ?? '') === 'XMLHttpRequest') {
      while (ob_get_level()) { ob_end_clean(); }
      header('Content-Type: application/json');
      echo json_encode(['success' => (bool) $ok, 'error' => $errorDetail ?? null]);
      exit();
    }
    header("Location: known_users.php");
    exit();
  }
}


while (ob_get_level() > 0) { ob_end_clean(); }
header('Content-Type: application/json');
if ($_SERVER['REQUEST_METHOD'] === 'POST') { http_response_code(400); echo json_encode(['success' => false, 'error' => 'Nothing changed.']); exit(); }
$bDef = ['welcome' => 'Welcome back (user), glad to see you again!', 'vip' => 'ATTENTION! A very important person has entered the chat, welcome (user)', 'mod' => 'MOD ON DUTY! Welcome in (user), the power of the sword has increased!'];
try {
    $bRes = $db->query('SELECT default_welcome_message, default_vip_welcome_message, default_mod_welcome_message FROM streamer_preferences WHERE id = 1');
    $bRow = $bRes ? $bRes->fetch_assoc() : null;
    if ($bRow) { foreach (['welcome' => 'default_welcome_message', 'vip' => 'default_vip_welcome_message', 'mod' => 'default_mod_welcome_message'] as $k => $c) { if (isset($bRow[$c]) && $bRow[$c] !== '') $bDef[$k] = $bRow[$c]; } }
} catch (mysqli_sql_exception $e) { $bDef = null; }
echo json_encode(['success' => true, 'defaults' => $bDef, 'total' => $totalUsers, 'banned' => is_array($bannedUsersCache) ? (object) $bannedUsersCache : new stdClass(), 'cache_warning' => $cacheWarningMessage]);
